message.reasoning_content:
Now I need to rewrite the CurrencyListPage to:

1. Add a "Показать ещё" (Show more) button that loads the next page when `hasMore` is true
2. Hide the button when `hasMore == false` (end of pagination)
3. Refresh data on screen regain focus using `WidgetsBindingObserver`

Key changes needed:
- Add `WidgetsBindingObserver` mixin to track lifecycle
- Track current page number for pagination
- Store `_allCurrencies` properly and append new items when "Show more" is pressed
- Add a loading state for the "show more" button
- Hide "Show more" button when `hasMore == false`
- On resume, fetch fresh data with base currency (page 0)

Let me design the new implementation:

```dart
import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  // Pagination state
  int _currentPage = 0;
  bool _hasMore = false;
  bool _isLoadingMore = false;

  List<CurrencyModel> _allCurrencies = [];

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _loadInitialData();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      // Screen regained focus - refresh with base currency (page 0)
      _refreshList();
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadInitialData() async {
    final currencyRepository = context.read<CurrencyRepository>();

    setState(() {
      _currentPage = 0;
      _isLoadingMore = false;
    });

    final CurrencyPage page = await currencyRepository.fetchRates(const CurrencyPageRequest());

    if (!mounted) return;

    setState(() {
      _allCurrencies = page.items;
      _filteredCurrenciesNotifier.value = List.from(page.items);
      _hasMore = page.hasMore;
      _currentPage = 1; // Next page to load
    });

    await currencyRepository.saveCurrencyList(_allCurrencies);

    _fadeController.forward();
  }

  Future<void> _loadMoreData() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() {
      _isLoadingMore = true;
    });

