  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late Future<void> _loadFuture;

  int _currentPage = 0;
  bool _hasMore = false;

  List<CurrencyModel> _allCurrencies = [];

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _filteredCurrenciesNotifier = ValueNotifier([]);
    _loadFuture = _loadInitialData(0, const []);
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _refreshList();
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    super.dispose();
  }

  Future<void> _loadInitialData(int page, List<CurrencyModel> initialItems) async {
    final currencyRepository = context.read<CurrencyRepository>();

    setState(() {
      _currentPage = page;
      _allCurrencies = List.from(initialItems);
    });

    final CurrencyPage result = await currencyRepository.fetchRates(const CurrencyPageRequest());

    if (!mounted) return;

    setState(() {
      _allCurrencies = List.from(result.items);
      _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
      _hasMore = result.hasMore;
    });

    await currencyRepository.saveCurrencyList(_allCurrencies);
  }

  Future<void> _loadMoreData() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() => _isLoadingMore = true);

    final currencyRepository = context.read<CurrencyRepository>();
    final CurrencyPage page = await currencyRepository.fetchRates(
      CurrencyPageRequest(page: _currentPage + 1),
    );

    if (!mounted) return;

    setState(() {
      _allCurrencies.addAll(page.items);
      _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
      _hasMore = page.hasMore;
      _currentPage++;
      _isLoadingMore = false;
    });

    await currencyRepository.saveCurrencyList(_allCurrencies);
  }

  Future<void> _refreshList() async {
    if (_isLoadingMore) return;
    setState(() => _isInitialLoading = true);
    _filteredCurrenciesNotifier.value = const [];
    _loadFuture = _loadInitialData(0, []);
    await _loadFuture;
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  bool _isInitialLoading = true;
  bool _isLoadingMore = false;
  late final AnimationController _fadeController;

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;
