      final CurrencyPage page = await currencyRepository.fetchRates(const CurrencyPageRequest());

      if (!mounted) return;

      final List<CurrencyModel> items = List.from(page.items);
      setState(() {
        _allCurrencies = items;
        _filteredCurrenciesNotifier.value = List.from(items);
        _hasMore = page.hasMore;
      });

      await currencyRepository.saveCurrencyList(_allCurrencies);

      if (mounted) {
        _fadeController ??= AnimationController(
          duration: Duration(milliseconds: 400),
          vsync: this,
        );
        _fadeController!.forward();
      }
    } catch (_) {
      // silently handle errors; UI stays empty
    } finally {
      if (mounted) {
        setState(() => _isFirstLoad = true);
      }
    }
  }

  Future<void> _loadMoreData() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() => _isLoadingMore = true);

    final currencyRepository = context.read<CurrencyRepository>();

    try {
      final CurrencyPage page = await currencyRepository.fetchRates(
        CurrencyPageRequest(page: _currentPage + 1),
      );

      if (!mounted) return;

      setState(() {
        _allCurrencies.addAll(page.items);
        _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
        _hasMore = page.hasMore;
        _currentPage++;
        _isLoadingMore = false;
      });

      await currencyRepository.saveCurrencyList(_allCurrencies);
    } catch (_) {
      if (mounted) setState(() => _isLoadingMore = false);
    }
  }

  Future<void> _refreshList() async {
    final currencyRepository = context.read<CurrencyRepository>();

    try {
      final CurrencyPage page = await currencyRepository.fetchRates(const CurrencyPageRequest());

      if (!mounted) return;

      setState(() {
        _allCurrencies = List.from(page.items);
        _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
        _hasMore = page.hasMore;
      });

      await currencyRepository.saveCurrencyList(_allCurrencies);

      if (mounted && _fadeController != null) {
        _fadeController!.reset();
        _fadeController!.forward();
      }
    } catch (_) {}
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;
    return Scaffold(
      appBar: AppBar(title: Text(loc.currencyRate)),
      body: ValueListenableBuilder<List<CurrencyModel>>(
        valueListenable: _filteredCurrenciesNotifier,
        builder: (BuildContext context, List<CurrencyModel> data, _) {
          if (_isFirstLoad && data.isEmpty) return const SizedBox.shrink();

          final animationOpacity = _fadeController != null ? _fadeController!.view : const AlwaysStoppedAnimation(1.0);

          return FadeTransition(
            opacity: animationOpacity,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ListView.builder(
                    itemCount: data.length + (_hasMore ? 1 : 0),
                    itemBuilder: (BuildContext context, int index) {
                      if (index == data.length && _hasMore) {
                        return Center(
                          child: Padding(
                            padding: const EdgeInsets.all(24.0),
                            child: ElevatedButton(
                              onPressed: _isLoadingMore ? null : _loadMoreData,
                              child: _isLoadingMore
                                  ? SizedBox(
                                      width: 20,
                                      height: 20,
                                      child: CircularProgressIndicator(strokeWidth: 2),
                                    )
                                  : Text(loc.showMore),
                            ),
                          ),
                        );
                      }

                      final CurrencyModel currency = data[index];

                      return Padding(
                        key: ValueKey(currency.id),
                        padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                        child: CurrencyCard(model: currency),
                      );
                    },
                    padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}

